create extension if not exists pgcrypto;
create type public.app_role as enum ('investor','portfolio_manager','investment_reviewer','compliance_officer','admin');
create type public.workflow_state as enum ('draft','investment_review','compliance_approval','published','rejected');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',role public.app_role not null default 'investor',created_at timestamptz not null default now());
create table public.suitability_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),approved_band text not null check(approved_band in ('Conservative','Balanced','Aggressive')),approved_score int check(approved_score between 0 and 100),effective_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.portfolios(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.portfolio_versions(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references public.portfolios(id),version int not null,band text not null check(band in ('Conservative','Balanced','Aggressive')),target_return numeric not null,volatility numeric not null,risk_score int not null,definition jsonb not null default '{}',workflow_state public.workflow_state not null default 'draft',created_by uuid not null references public.profiles(id),reviewed_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),published_at timestamptz,created_at timestamptz not null default now(),unique(portfolio_id,version));
create table public.governance_events(id bigint generated always as identity primary key,entity_type text not null,entity_id uuid not null,action text not null,actor_id uuid not null references public.profiles(id),metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.simulation_runs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),portfolio_version_id uuid not null references public.portfolio_versions(id),initial_amount numeric not null,monthly_contribution numeric not null,horizon_years int not null,seed bigint not null,paths int not null,results jsonb not null,created_at timestamptz not null default now());
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in ('portfolio_manager','investment_reviewer','compliance_officer','admin'))$$;
alter table public.profiles enable row level security;alter table public.suitability_profiles enable row level security;alter table public.portfolios enable row level security;alter table public.portfolio_versions enable row level security;alter table public.governance_events enable row level security;alter table public.simulation_runs enable row level security;
create policy "own profile" on public.profiles for select using(id=auth.uid());create policy "own suitability" on public.suitability_profiles for select using(user_id=auth.uid());create policy "published portfolios" on public.portfolios for select using(active=true or public.is_staff());create policy "published versions" on public.portfolio_versions for select using(workflow_state='published' or public.is_staff());create policy "own simulations" on public.simulation_runs for select using(user_id=auth.uid());create policy "staff governance read" on public.governance_events for select using(public.is_staff());
create or replace function public.prevent_governance_mutation() returns trigger language plpgsql as $$begin raise exception 'Governance events are append-only';end;$$;
create trigger governance_immutable before update or delete on public.governance_events for each row execute function public.prevent_governance_mutation();
